        + (state.missing ? ' · <span style="color:var(--ks-warn)">not found — showing defaults. Saving will create it here.</span>' : '')
        + ' · ' + esc(String(fields.length + unknowns.length)) + ' of ' + esc(String(total)) + ' shown'
